import{_ as l,o as a,c as e,a6 as t}from"./chunks/framework.BBIckNDn.js";const p=JSON.parse('{"title":"ビルド時間 — incremental build・PCH・Unity Build・C++でビルドが遅くなる理由","description":"","frontmatter":{"title":"ビルド時間 — incremental build・PCH・Unity Build・C++でビルドが遅くなる理由","study":{"source":"C++ Wiki","kind":"本文","status":"既存原稿","summary":"#includeの爆発: #include だけで数万行が翻訳単位に貼り付く(プリプロセッサ)。100個の.cppが同じヘッダーを含めば、同じ数万行を100回パースする テンプレートの再実体化: vector を使う全翻訳単位で実体化→リンカが重複を捨てる。「作っては捨てる」の山(→ 実体化)"}},"headers":[],"relativePath":"tools/build/build-speed.md","filePath":"tools/build/build-speed.md"}'),s={name:"tools/build/build-speed.md"};function n(d,i,o,r,u,c){return a(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="ビルド時間-—-incremental-build・pch・unity-build・c-でビルドが遅くなる理由" tabindex="-1">ビルド時間 — incremental build・PCH・Unity Build・C++でビルドが遅くなる理由 <a class="header-anchor" href="#ビルド時間-—-incremental-build・pch・unity-build・c-でビルドが遅くなる理由" aria-label="Permalink to &quot;ビルド時間 — incremental build・PCH・Unity Build・C++でビルドが遅くなる理由&quot;">​</a></h1><h2 id="なぜc-のビルドは遅いのか-原因の理解が対策の半分" tabindex="-1">なぜC++のビルドは遅いのか(原因の理解が対策の半分) <a class="header-anchor" href="#なぜc-のビルドは遅いのか-原因の理解が対策の半分" aria-label="Permalink to &quot;なぜC++のビルドは遅いのか(原因の理解が対策の半分)&quot;">​</a></h2><ol><li><strong>#includeの爆発</strong>: <code>#include &lt;vector&gt;</code> だけで数万行が翻訳単位に貼り付く(<a href="/study/runtime/cpp-internals/build-pipeline-journey.html">プリプロセッサ</a>)。100個の.cppが同じヘッダーを含めば、<strong>同じ数万行を100回パース</strong>する</li><li><strong>テンプレートの再実体化</strong>: <code>vector&lt;int&gt;</code> を使う全翻訳単位で実体化→リンカが重複を捨てる。「作っては捨てる」の山(→ <a href="/study/runtime/cpp-internals/template-instantiation-and-inline.html">実体化</a>)</li><li><strong>最適化・LTO</strong>: -O2の解析、リンク時最適化は全プログラム解析</li><li><strong>ヘッダー依存の連鎖</strong>: 1つのヘッダー変更が、それをincludeする全.cppの再コンパイルを誘発(<strong>変更の波及範囲=ビルド時間</strong>——<a href="/study/design/foundations/cohesion-and-coupling.html">結合度</a>が物理現象になったもの)</li></ol><h2 id="対策1-incremental-build-差分ビルド-を機能させる" tabindex="-1">対策1: incremental build(差分ビルド)を機能させる <a class="header-anchor" href="#対策1-incremental-build-差分ビルド-を機能させる" aria-label="Permalink to &quot;対策1: incremental build(差分ビルド)を機能させる&quot;">​</a></h2><ul><li>ビルドシステムは「変更されたファイル+その影響先」だけ再ビルドする(→ <a href="/study/tools/build/what-is-build.html">ビルドとは</a>)。<strong>これが効かない構造</strong>にしてしまうのが問題: <ul><li>「何でも入りヘッダー」(全域includeされる <code>common.h</code> に頻繁に触る)→ 毎回全ビルド</li><li>ヘッダーに実装を書きすぎる → 変更のたび広範囲が再コンパイル</li></ul></li><li><strong>対策はヘッダー衛生</strong>: 前方宣言でincludeを減らす(<a href="/study/runtime/cpp-internals/translation-units-and-headers.html">翻訳単位</a>)、実装は.cppへ、変更頻度の高いものを上流ヘッダーに置かない、includeの棚卸し(include-what-you-use)</li></ul><h2 id="対策2-pch-precompiled-header" tabindex="-1">対策2: PCH (Precompiled Header) <a class="header-anchor" href="#対策2-pch-precompiled-header" aria-label="Permalink to &quot;対策2: PCH (Precompiled Header)&quot;">​</a></h2><p>「ほぼ全員が使い、ほぼ変更されないヘッダー群」(標準ライブラリ、エンジンAPI)を<strong>1回だけコンパイルした状態で保存</strong>し、各翻訳単位はそこから開始する仕組み。</p><div class="language-cmake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># CMake 3.16+</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">target_precompile_headers(game_core </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PRIVATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;vector&gt; &lt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; &lt;memory&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;engine/core.h&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><ul><li>効果は大(体感数倍もある)。代償: PCH対象を変更すると<strong>全再ビルド</strong>/「PCHに入っているから」とincludeを書かない癖がつくと依存が見えなくなる(PCH無し環境で壊れる)</li><li>C++20の<strong>モジュール</strong>が根本解決の方向だが、ツールチェーンの成熟待ちの過渡期(2020年代半ば時点)</li></ul><h2 id="対策3-unity-build-jumbo-build" tabindex="-1">対策3: Unity Build(Jumbo Build) <a class="header-anchor" href="#対策3-unity-build-jumbo-build" aria-label="Permalink to &quot;対策3: Unity Build(Jumbo Build)&quot;">​</a></h2><p>複数の.cppを <code>#include</code> で1つの巨大.cppにまとめてコンパイルする力技(<strong>Unityエンジンとは無関係</strong>。名前が同じだけなので注意)。</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// unity_batch_01.cpp(生成物)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;enemy.cpp&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;player.cpp&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;quest.cpp&quot;</span></span></code></pre></div><ul><li>効果: ヘッダーの重複パースとテンプレート再実体化が激減(フルビルドが数分の一になる例も)。UEのUBTは既定でこれを行う(Adaptive Unity Build)</li><li>代償: <ul><li><strong>翻訳単位の分離が壊れる</strong>: 別ファイルの <code>static</code>/無名namespaceが衝突、usingが漏れる——「Unity Buildでだけビルドが壊れる/通ってしまう」</li><li>差分ビルドが粗くなる(1ファイル変更でバッチ丸ごと再コンパイル)</li></ul></li><li>CMake: <code>set(CMAKE_UNITY_BUILD ON)</code></li></ul><h2 id="対策4-その他の実務手段" tabindex="-1">対策4: その他の実務手段 <a class="header-anchor" href="#対策4-その他の実務手段" aria-label="Permalink to &quot;対策4: その他の実務手段&quot;">​</a></h2><ul><li><strong>Ninja</strong>(Makeより高速なスケジューリング)+並列数の適正化</li><li><strong>分散ビルド</strong>(IncrediBuild、FASTBuild、sccache)——大規模スタジオの標準装備</li><li>リンク時間: 分割ライブラリ、増分リンク、mold/lldなど高速リンカ</li><li><strong>計測</strong>: Clangの <code>-ftime-trace</code>、ninjaのログで「どのファイル・どのヘッダーが遅いか」を特定してから直す(ビルド時間も<a href="/study/design/foundations/yagni-kiss-dry.html">計測してから最適化</a>)</li></ul><h2 id="c-unityとの対応" tabindex="-1">C#/Unityとの対応 <a class="header-anchor" href="#c-unityとの対応" aria-label="Permalink to &quot;C#/Unityとの対応&quot;">​</a></h2><ul><li>C#のコンパイルが速い理由: ヘッダーがない(メタデータ参照)、テンプレート再実体化がない(ジェネリックは実行時)、パース対象が書いた分だけ——<strong>C++の遅さの原因が構造的に存在しない</strong></li><li>Unityで遅いのは主にドメインリロードとアセット処理で、コンパイル自体は速い。Assembly Definition分割は「変更の波及範囲を狭める」というこのページと同じ思考(→ <a href="/study/languages/csharp/headers-vs-asmdef.html">第9部</a>)</li><li>UEのビルドが遅いのは、まさにこのページの問題との戦い(UBTのPCH+Unity Build+モジュール分割は全部このページの対策の実装)</li></ul><h2 id="実務指針-優先順" tabindex="-1">実務指針(優先順) <a class="header-anchor" href="#実務指針-優先順" aria-label="Permalink to &quot;実務指針(優先順)&quot;">​</a></h2><ol><li>計測(どこが遅い?)</li><li>ヘッダー衛生(前方宣言・include削減)——設計改善でもある</li><li>PCH(手軽で効果大)</li><li>Unity Build(効果大だが規律が要る)</li><li>ハードウェア・分散(金で解決)</li></ol><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>C++のビルドが遅い構造的理由を2つ(include爆発・テンプレート再実体化)説明できますか。</li><li>PCHの効果と2つの代償は?</li><li>Unity Buildが壊す「分離」とは何ですか。</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p>samples/cmake_demo/ に <code>set(CMAKE_UNITY_BUILD ON)</code> を試し、(a) フルビルド時間の変化(小規模なので差は小さい)、(b) 2つの.cppに同名のstatic関数を書いて衝突が起きることを確認してください。</p><hr><p>前: <a href="/study/tools/build/build-configurations.html">ビルド構成</a> | <a href="/study/tools/build/">カテゴリ目次</a> | 次: <a href="/study/tools/build/debugging-and-analysis.html">品質のための道具</a></p>`,25)])])}const g=l(s,[["render",n]]);export{p as __pageData,g as default};
